export default function GreenhousePage() {
  const [plants, setPlants] = useState([]);

  const onMount = async () => {
    const response = await fetch('/api/plants');
    const data = await response.json();
    setPlants(data);
  };

  return (
    <div>
      <PlantPicker
        plants={plants}
        onPlantPicker={(plant) => addPlant(plant)}
      />
      <WateringForm
        onWateringForm={(amount, plantId) => addWatering(amount, plantId)}
      />
      <div>
        {plants.map((plant) => (
          <PlantCard
            key={plant.id}
            plant={plant}
            onPlantPicker={(newPlant) => addPlant(newPlant)}
          />
        ))}
      </div>
    </div>
  );
}
